package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct {
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierEntry struct {
	TierLimit decimal.Decimal // PIC 9(6)V99 @0 len=8
	TierRate  decimal.Decimal // PIC 9V99 @8 len=3
}

type TierTable struct {
	TierEntry [4]TierEntry
}

var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var tierTable TierTable
var salesRec SalesRec
var inputDone bool

// helpers

func parseDecimalDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	// s contains only digits (possibly sign)
	neg := false
	if len(s) > 0 && s[0] == '-' {
		neg = true
		s = s[1:]
	}
	// remove any non-digit
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		digits = "0"
	}
	d, _ := decimal.NewFromString(digits)
	if neg {
		d = d.Neg()
	}
	d = d.Shift(-scale)
	return d
}

func formatNumericEdited(val decimal.Decimal, pic string) string {
	// Determine scale = number of chars after '.'
	scale := 0
	dotIdx := strings.Index(pic, ".")
	if dotIdx >= 0 {
		scale = len(pic) - dotIdx - 1
	}
	// Integer part length in pic = count of Z and 9 and commas before dot
	intPic := pic
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// Round/truncate value to scale for display? MOVE already has correct scale, but ensure
	// We truncate toward? For display, value already has scale. Just format.
	// Ensure val is rounded to scale? Use string with scale.
	// Use absolute value; no sign in these pics
	isNeg := val.Sign() < 0
	if isNeg {
		val = val.Neg()
	}
	// Quantize to scale by truncating? The value stored is already at scale.
	// Use Round to avoid floating noise, but truncating is fine.
	val = val.Truncate(int32(scale))

	// Get integer and fractional strings
	// val.Shift(scale) is integer representation
	shifted := val.Shift(int32(scale))
	// shifted may have fractional .00 due to decimal representation, truncate
	shifted = shifted.Truncate(0)
	s := shifted.String() // integer string, may be negative already handled
	if isNeg {
		// s already positive
	}
	// Remove sign if any
	if len(s) > 0 && s[0] == '-' {
		s = s[1:]
	}
	// s is integer of val*10^scale
	// pad left with zeros to at least scale+1 digits
	if len(s) <= scale {
		s = strings.Repeat("0", scale+1-len(s)) + s
	}
	intPart := s[:len(s)-scale]
	fracPart := ""
	if scale > 0 {
		fracPart = s[len(s)-scale:]
	}
	// High-order truncation: keep only low-order intDigits digits
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	// Pad intPart to intDigits with leading zeros
	if len(intPart) < intDigits {
		intPart = strings.Repeat("0", intDigits-len(intPart)) + intPart
	}

	// Build integer formatted segment including commas
	// intPic includes commas and Z/9 placeholders
	// We need to map each placeholder position to digit
	// Collect placeholder indices
	type ph struct {
		isComma bool
		kind    byte // 'Z' or '9'
	}
	var placeholders []ph
	var picIntChars []byte
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == ',' {
			placeholders = append(placeholders, ph{isComma: true})
			picIntChars = append(picIntChars, ',')
		} else if c == 'Z' || c == '9' {
			placeholders = append(placeholders, ph{isComma: false, kind: byte(c)})
			picIntChars = append(picIntChars, byte(c))
		}
	}
	// placeholders length == intDigits + numCommas ; but digits align to non-comma placeholders in order
	digitIdx := 0
	intFormatted := make([]byte, len(intPic))
	for i, ch := range intPic {
		if ch == ',' {
			intFormatted[i] = ','
		} else {
			// Z or 9
			d := intPart[digitIdx]
			digitIdx++
			intFormatted[i] = d
		}
	}
	// Apply Z suppression: leading zeros replaced with spaces, commas in suppressed zone become spaces
	// Find last non-suppressed position: suppression continues while we are on Z positions and digit is '0'
	// Once we encounter a non-zero digit on a Z, suppression ends. Also any '9' ends suppression even if zero? Actually 9 always prints digit, so suppression stops at first 9 position.
	suppressing := true
	for i := 0; i < len(intFormatted); i++ {
		chPic := intPic[i]
		if chPic == ',' {
			if suppressing {
				intFormatted[i] = ' '
			} else {
				intFormatted[i] = ','
			}
		} else if chPic == 'Z' {
			if suppressing {
				if intFormatted[i] == '0' {
					intFormatted[i] = ' '
				} else {
					suppressing = false
				}
			}
		} else if chPic == '9' {
			// 9 always shows digit, and ends suppression
			suppressing = false
		}
	}
	result := string(intFormatted)
	if dotIdx >= 0 {
		result += "." + fracPart
	}
	return result
}

func storeComm(v decimal.Decimal) {
	// PIC 9(6)V99 : 6 integer digits, 2 decimals, keep low-order
	// Round already done to scale 2, just enforce truncation/padding and overflow drop
	// For overflow, keep low-order digits: we can implement via modulo 10^(6+2)
	// But values in this program won't overflow; just truncate to 2 decimals and keep as is
	WsComm = v.Truncate(2)
	// Simulate overflow drop if needed
	scale := int32(2)
	intDigits := 6
	mod := decimal.NewFromInt(1).Shift(int32(intDigits + int(scale))) // 10^(8)
	shifted := WsComm.Shift(scale).Truncate(0)
	// handle negative
	sign := shifted.Sign()
	if sign < 0 {
		shifted = shifted.Neg()
	}
	if shifted.Cmp(mod) >= 0 {
		shifted = shifted.Mod(mod)
		if sign < 0 {
			shifted = shifted.Neg()
		}
		WsComm = shifted.Shift(-scale)
	}
}

func storeTotal(v decimal.Decimal) {
	WsTotal = v.Truncate(2)
	intDigits := 9
	scale := int32(2)
	mod := decimal.NewFromInt(1).Shift(int32(intDigits + int(scale)))
	shifted := WsTotal.Shift(scale).Truncate(0)
	sign := shifted.Sign()
	if sign < 0 {
		shifted = shifted.Neg()
	}
	if shifted.Cmp(mod) >= 0 {
		shifted = shifted.Mod(mod)
		if sign < 0 {
			shifted = shifted.Neg()
		}
		WsTotal = shifted.Shift(-scale)
	}
}

func main() {
	MAIN_PARA()
}

func MAIN_PARA() {
	INIT_PARA()
	file, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		file = nil
	}
	var scanner *bufio.Scanner
	if file != nil {
		defer file.Close()
		scanner = bufio.NewScanner(file)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
	}
	READ_PARA(scanner)
	for !inputDone {
		PROCESS_PARA(scanner)
	}
	if file != nil {
		file.Close()
	}
	SUMMARY_PARA()
}

func INIT_PARA() {
	tierTable.TierEntry[0].TierLimit = decimal.NewFromInt(1000).Shift(0) // 1000.00
	// Use NewFromString to preserve exact decimals
	tierTable.TierEntry[0].TierLimit = parseDecimalDigits("100000", 2)
	tierTable.TierEntry[0].TierRate = parseDecimalDigits("250", 2) // 2.50
	tierTable.TierEntry[1].TierLimit = parseDecimalDigits("500000", 2)
	tierTable.TierEntry[1].TierRate = parseDecimalDigits("400", 2)
	tierTable.TierEntry[2].TierLimit = parseDecimalDigits("2000000", 2)
	tierTable.TierEntry[2].TierRate = parseDecimalDigits("550", 2)
	tierTable.TierEntry[3].TierLimit = parseDecimalDigits("99999999", 2)
	tierTable.TierEntry[3].TierRate = parseDecimalDigits("725", 2)
}

func READ_PARA(scanner *bufio.Scanner) {
	if scanner == nil {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	if !scanner.Scan() {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	line := scanner.Text()
	// Pad with spaces to record length 12
	if len(line) < 12 {
		line += strings.Repeat(" ", 12-len(line))
	}
	if len(line) > 12 {
		line = line[:12]
	}
	srId := line[0:4]
	srSalesRaw := line[4:12]
	salesRec.SrId = srId
	salesRec.SrSales = parseDecimalDigits(srSalesRaw, 2)
}

func PROCESS_PARA(scanner *bufio.Scanner) {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && WsTier == 0; WsIdx++ {
		if salesRec.SrSales.Cmp(tierTable.TierEntry[WsIdx-1].TierLimit) <= 0 {
			WsTier = WsIdx
		}
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE(WS-TIER) /100
	rate := tierTable.TierEntry[WsTier-1].TierRate
	computed := salesRec.SrSales.Mul(rate).Shift(-2).Round(2)
	storeComm(computed)
	storeTotal(WsTotal.Add(WsComm))
	WsCount++
	WsSalesEd = formatNumericEdited(salesRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatNumericEdited(rate, "9.99")
	WsCommEd = formatNumericEdited(WsComm, "ZZZ,ZZ9.99")
	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	// WsTier prints as PIC 9 (zero-padded 1 digit)
	tierStr := fmt.Sprintf("%01d", WsTier)
	fmt.Printf("%s T%s %s %s%% %s\n", salesRec.SrId, tierStr, WsSalesEd, WsRateEd, WsCommEd)
	READ_PARA(scanner)
}

func SUMMARY_PARA() {
	WsTotalEd = formatNumericEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("REPS: %s TOTAL: %s\n", countStr, WsTotalEd)
}
